import datetime
import time
import re
import pytz
from tzlocal import get_localzone_name

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result, log_step
from taf.rfrl.procedures.resources.python.counters.bts.exceptions import IncorrectNumberOfMeasurements, \
    IncorrectMeasurementInterval, IncorrectDateTime, IncorrectParameterFormat, IncorrectParameterValue


def get_datetime_of_current_measurement_frame(measurement_interval=15):
    """
    Gets date and time (in datetime format) for current measurement frame start.
    :param measurement_interval: measurement interval defined in minutes, related to single measurement frame duration.
                                 One of following values possible to set: 5, 15, 30, or 60. It's also possible to use
                                 string value parameter in minutes format, e.g. '15min'. Defaults to 15.
    :type measurement_interval: int or str

    :return: Date of the current measurement frame start in datetime format without seconds, e.g.: (2025, 3, 27, 12, 45)
    :rtype: datetime.datetime object

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'measurement_interval' parameter
    :raises: IncorrectMeasurementInterval when measurement_interval value is incorrect
    """
    measurement_interval = _convert_time_parameter_from_minutes_format_to_int(time_parameter=measurement_interval)
    _verify_measurement_interval_parameter(measurement_interval=measurement_interval)

    now = datetime.datetime.now()
    now_full_min = now.replace(second=0, microsecond=0)
    minutes_after_measurement_start = now_full_min.minute % measurement_interval

    current_measurement_frame_datetime = now_full_min - datetime.timedelta(minutes=minutes_after_measurement_start)
    log_result(f"Current measurement frame start time is: {current_measurement_frame_datetime}")

    return current_measurement_frame_datetime


@log_input_and_output
def get_datetime_of_next_measurement_frame(measurement_interval=15, add_local_timezone=False):
    """
    Gets date and time (in datetime format) for next measurement frame start. If actual time is exactly the same as
    current measurement frame start, actual time is returned.
    :param measurement_interval: measurement interval defined in minutes, related to single measurement frame duration.
                                 One of following values possible to set: 5, 15, 30, or 60. It's also possible to use
                                 string value parameter in minutes format, e.g. '15min'. Defaults to 15.
    :type measurement_interval: int or str
    :param add_local_timezone: if True, local timezone info will be added to returned datetime object. Defaults to False.
    :type add_local_timezone: bool

    :return: Date of the next measurement frame start in datetime format without seconds, e.g.: (2025, 10, 21, 13, 30)
             or datetime.datetime(2025, 10, 21, 13, 30, tzinfo=<DstTzInfo 'Europe/Warsaw' CEST+2:00:00 DST>) if
             'add_local_timezone' is True
    :rtype: datetime.datetime object

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'measurement_interval' parameter
    :raises: IncorrectMeasurementInterval when measurement_interval value is incorrect
    """
    return _get_datetime_of_next_measurement_frame(measurement_interval=measurement_interval,
                                                   add_local_timezone=add_local_timezone)


@log_input_and_output
def get_datetime_of_the_end_of_measurements(measurements_start, measurement_interval=15, count_of_measurement_frames=1):
    """
    Gets date and time (in datetime format) for the end of measurement. Duration of measurement depends on parameters
    'measurement_interval' and 'count_of_measurement_frames'.
    :param measurements_start: datetime of first measurement frame start.
    :type measurements_start: datetime or str(in format '%Y-%m-%d %H:%M:%S.%f')
    :param measurement_interval: measurement interval defined in minutes, related to single measurement frame duration.
                                 One of following values possible to set: 5, 15, 30, or 60. It's also possible to use
                                 string value parameter in minutes format, e.g. '15min'. Defaults to 15.
    :type measurement_interval: int or str
    :param count_of_measurement_frames: count of measurement frames for overall measurement, defaults to 1.
    :type count_of_measurement_frames: int or str

    :return: Date of the end of measurement.
    :rtype: datetime.datetime object

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'measurement_interval' parameter
    :raises: IncorrectMeasurementInterval when measurement_interval value is incorrect
    """
    measurements_start = _convert_str_to_datetime_format(measurements_start)
    measurement_interval = _convert_time_parameter_from_minutes_format_to_int(time_parameter=measurement_interval)
    _verify_measurement_interval_parameter(measurement_interval)

    measurements_duration_in_seconds = measurement_interval * 60 * int(count_of_measurement_frames)
    measurement_stop_datetime = measurements_start + datetime.timedelta(seconds=measurements_duration_in_seconds)
    log_result(f"Counted measurement frame stop will happen in {measurements_duration_in_seconds} sec. "
               f"Accurate time is: {measurement_stop_datetime}")

    return measurement_stop_datetime


@log_input_and_output
def wait_for_measurement(datetime_of_measurement):
    """
    Waits for measurement's start or stop, based on current time and provided datetime of measurement.
    :param datetime_of_measurement: datetime (optionally with local timezone) of measurement frame stop/start.
    :type datetime_of_measurement: datetime or str(in format '%Y-%m-%d %H:%M:%S.%f')

    :raises: IncorrectDateTime when provided datetime of measurement is out of date (older than current date)
    """
    datetime_of_measurement = _convert_str_to_datetime_format(date_time=datetime_of_measurement)

    now = datetime.datetime.now()
    if datetime_of_measurement.tzinfo:
        local_timezone = pytz.timezone(get_localzone_name())
        now = local_timezone.localize(now, is_dst=None)
    time_delta = datetime_of_measurement - now

    if time_delta.days < 0:
        raise IncorrectDateTime("Provided datetime of measurement is out of date")

    log_step(f"Waiting {time_delta.seconds} sec for measurement frame, current time is: {now}...")
    time.sleep(time_delta.total_seconds())


@log_input_and_output
def wait_until_moment_before_next_measurement(measurement_interval=15, time_before_next_measurement=5):
    """
    Waits until specified moment before next measurement.
    :param measurement_interval: measurement interval expressed in minutes, should be equal 5, 10, 15 or 60. Defaults to 15.
    :type measurement_interval: int
    :param time_before_next_measurement: time in minutes to designate datetime before next measurement, defaults to 5. Parameter value cannot be
                                         greater than `measurement_interval` parameter value.
    :type time_before_next_measurement: int

    :raises: IncorrectMeasurementInterval when `measurement_interval` parameter value is incorrect
    :raises: IncorrectParameterValue when `time_before_next_measurement` parameter value is incorrect
    :raises: IncorrectDateTime when calculated datetime of moment to wait is out of date
    """
    if measurement_interval < time_before_next_measurement:
        raise IncorrectParameterValue("Parameter 'time_before_next_measurement' cannot be greater than 'measurement_interval'")

    target_datetime = _convert_str_to_datetime_format(
        date_time=_get_datetime_of_moment_before_next_measurement(measurement_interval=measurement_interval,
                                                                  time_before_next_measurement=time_before_next_measurement))
    log_result(f"The moment before next measurement is calculated on: {target_datetime}")

    now = datetime.datetime.now()
    time_delta = target_datetime - now

    if time_delta.days < 0:
        raise IncorrectDateTime("Calculated datetime of moment to wait is out of date")

    log_step(f"Waiting {time_delta.seconds} sec for the moment when {time_before_next_measurement}min until next measurement")
    time.sleep(time_delta.total_seconds())


@log_input_and_output
def get_count_of_measurement_frames_based_on_overall_time(measurement_time, measurement_interval):
    """
    Gets count of measurement frames based on overall measurement time and measurement interval (frame duration).
    :param measurement_time: duration (in minutes) of overall measurement, e.g. 60. It's also possible to use
                             string value parameter in minutes format, e.g. '60min'
    :type measurement_time: int or str
    :param measurement_interval: measurement interval defined in minutes, related to single measurement frame duration.
                                 One of following values possible to set: 5, 15, 30, or 60. It's also possible to use
                                 string value parameter in minutes format, e.g. '15min'
    :type measurement_interval: int or str

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'measurement_time' or
                                      'measurement_interval' parameters
    :raises: IncorrectNumberOfMeasurements when overall measurement duration doesn't match with measurement interval.
    """
    measurement_time = _convert_time_parameter_from_minutes_format_to_int(time_parameter=measurement_time)
    measurement_interval = _convert_time_parameter_from_minutes_format_to_int(time_parameter=measurement_interval)

    _verify_measurement_interval_parameter(measurement_interval)

    count_of_measurement_frames = measurement_time / measurement_interval

    if not count_of_measurement_frames.is_integer():
        raise IncorrectNumberOfMeasurements(f"Incorrect calculated measurement frames count, it should be integer "
                                            f"(measurement_time / measurement_interval)! "
                                            f"Actual value is: {count_of_measurement_frames}")

    return count_of_measurement_frames


@log_input_and_output
def convert_time_parameter_from_minutes_format_to_int(time_parameter):
    """
    Converts time parameter value in minutes format (str) to integer value.
    :param time_parameter: minutes format value, e.g. "45min" or "45 min" or "45" or 45
    :type time_parameter: str or int

    :return: minutes expressed in integer value
    :rtype: int

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'time_parameter' parameter
    """
    return _convert_time_parameter_from_minutes_format_to_int(time_parameter=time_parameter)


@log_input_and_output
def _get_datetime_of_next_measurement_frame(measurement_interval, add_local_timezone):
    """
    Gets date and time (in datetime format) for next measurement frame start. If actual time is exactly the same as
    current measurement frame start, actual time is returned.
    :param measurement_interval: measurement interval defined in minutes, related to single measurement frame duration.
                                 One of following values possible to set: 5, 15, 30, or 60. It's also possible to use
                                 string value parameter in minutes format, e.g. '15min'.
    :type measurement_interval: int or str
    :param add_local_timezone: if True, local timezone info will be added to returned datetime object.
    :type add_local_timezone: bool

    :return: Date of the next measurement frame start in datetime format without seconds, e.g.: (2025, 10, 21, 13, 30)
             or datetime.datetime(2025, 10, 21, 13, 30, tzinfo=<DstTzInfo 'Europe/Warsaw' CEST+2:00:00 DST>) if
             'add_local_timezone' is True
    :rtype: datetime.datetime object

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'measurement_interval' parameter
    :raises: IncorrectMeasurementInterval when measurement_interval value is incorrect
    """
    measurement_interval = _convert_time_parameter_from_minutes_format_to_int(time_parameter=measurement_interval)
    _verify_measurement_interval_parameter(measurement_interval=measurement_interval)

    now = datetime.datetime.now()
    now_full_min = now.replace(second=0, microsecond=0)
    minutes_to_next_measurement = measurement_interval - (now_full_min.minute % measurement_interval)

    if minutes_to_next_measurement == int(measurement_interval):
        if now.replace(microsecond=0) == now_full_min:
            log_result(f"Current time is exactly the same as counter measurement frame start: {now_full_min}")
            return now_full_min

    next_measurement_frame_datetime = now_full_min + datetime.timedelta(minutes=minutes_to_next_measurement)
    log_result(f"Next measurement frame start time is: {next_measurement_frame_datetime}")

    if add_local_timezone:
        local_timezone = pytz.timezone(get_localzone_name())
        next_measurement_frame_datetime = local_timezone.localize(next_measurement_frame_datetime, is_dst=None)

    return next_measurement_frame_datetime


@log_input_and_output
def _get_datetime_of_moment_before_next_measurement(measurement_interval, time_before_next_measurement):
    """
    Gets specified datetime of moment before next measurement.
    :param measurement_interval: measurement interval expressed in minutes, should be equal 5, 10, 15 or 60
    :type measurement_interval: int
    :param time_before_next_measurement: time in minutes to designate datetime before next measurement
    :type time_before_next_measurement: int

    :return: specified datetime of moment before next measurement in format "%Y-%m-%d %H:%M:%S.%f", e.g.: 2025-10-09 15:45:00.000000
    :rtype: str

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'measurement_interval' parameter
    :raises: IncorrectMeasurementInterval when `measurement_interval` parameter value is incorrect
    """

    datetime_of_next_measurement = _get_datetime_of_next_measurement_frame(measurement_interval=measurement_interval,
                                                                           add_local_timezone=False)
    datetime_of_next_measurement = _convert_str_to_datetime_format(date_time=datetime_of_next_measurement)

    if measurement_interval == time_before_next_measurement:
        return datetime_of_next_measurement.strftime("%Y-%m-%d %H:%M:%S.%f")

    now = datetime.datetime.now()
    target_time = datetime_of_next_measurement - datetime.timedelta(minutes=time_before_next_measurement)

    if now > target_time:
        target_time = datetime_of_next_measurement + datetime.timedelta(minutes=time_before_next_measurement)

    return target_time.strftime("%Y-%m-%d %H:%M:%S.%f")


@log_input_and_output
def _verify_measurement_interval_parameter(measurement_interval):
    """
    Verifies given measurement_interval parameter.
    :param measurement_interval: measurement interval expressed in minutes, should be equal 5, 10, 15 or 60
    :type measurement_interval: int

    :raises: IncorrectMeasurementInterval when measurement_interval value is incorrect
    """
    if int(measurement_interval) not in [5, 15, 30, 60]:
        raise IncorrectMeasurementInterval(f"Parameter 'measurement_interval' value has got not supported "
                                           f"value: {measurement_interval}")


@log_input_and_output
def _convert_time_parameter_from_minutes_format_to_int(time_parameter):
    """
    Converts time parameter value in minutes format (str) to integer value.
    :param time_parameter: minutes format value, e.g. "45min" or "45 min" or "45" or 45
    :type time_parameter: str or int

    :return: minutes expressed in integer value
    :rtype: int

    :raises: IncorrectParameterFormat when numeric minutes value not found in 'time_parameter' parameter
    """
    value = re.match(r'[0-9]+', str(time_parameter))

    if value is not None:
        return int(value.group())

    raise IncorrectParameterFormat(f"Numeric minutes value not found in provided parameter: '{time_parameter}'")


@log_input_and_output
def _convert_str_to_datetime_format(date_time):
    """
    Converts datetime from string type to datetime type. String must be expressed in '%Y-%m-%d %H:%M:%S.%f' format.
    If given datetime is currently datetime type, conversion will be skipped and datetime returned.
    :param date_time: datetime expressed in '%Y-%m-%d %H:%M:%S.%f' format
    :type date_time: str or datetime

    :return: datetime in '%Y-%m-%d %H:%M:%S.%f' format
    :rtype: datetime
    """
    if not isinstance(date_time, datetime.datetime):
        datetime_format = '%Y-%m-%d %H:%M:%S.%f'
        date_time = datetime.datetime.strptime(date_time, datetime_format)

    return date_time
